import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione al parallelismo","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffa.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffa.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione-al-parallelismo" tabindex="-1">Introduzione al parallelismo <a class="header-anchor" href="#introduzione-al-parallelismo" aria-label="Permalink to “Introduzione al parallelismo”">​</a></h1><p>Ora abbiamo terminato lo studio dei triangoli e cominciamo a pensare a figure con più di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> lati: la proprietà che più ci colpisce è che ci sono dei segmenti che non hanno punti in comune fra loro; viene da pensare, immaginando ad esempio un quadrato, se le rette che portano tali segmenti possono o no avere punti in comune. Questo ci porta a definire una particolare relazione fra le rette: il parallelismo.</p><blockquote><p>Il parallelismo è stato il concetto che ha mostrato ai matematici, dopo secoli di studi, il vero significato della geometria in particolare e della matematica in generale: dopo il <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1872</mn></mrow><annotation encoding="application/x-tex">1872</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1872</span></span></span></span> (congresso di Erlangen) la matematica non è stata più la stessa;</p><p>In questo capitolo cercheremo di studiare sia il concetto di parallelismo che di capire la nascita delle diverse geometrie (affine, proiettiva, topologica) che dallo studio del parallelismo hanno preso origine;</p><p>In altri capitoli vedremo di studiare le geometrie delle trasformazioni in modo analitico.</p></blockquote>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};